#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
public static partial class Extension05Tools {
static bool FineGrass(Transform t){return t.name.StartsWith("01a_Grass_")||t.name.StartsWith("Rock_Foot_01a_Grass_")||t.name.StartsWith("Lush_01a_Grass_")||t.name.StartsWith("Reference10001_Grass_")||t.name.StartsWith("Cliff_Foot_Grass_");}
static void GrassInspectOnly(){var s=Load("10005a");var lines=new System.Collections.Generic.List<string>();lines.Add("dirty="+s.isDirty);foreach(var g in All(s).Where(t=>t.name.ToLower().Contains("grass")).GroupBy(t=>FineGrass(t)?"generated fine grass":t.name)){lines.Add(g.Key+" total="+g.Count()+" active="+g.Count(t=>t.gameObject.activeInHierarchy));}foreach(var ter in All(s).Select(t=>t.GetComponent<Terrain>()).Where(t=>t)){lines.Add("TERRAIN "+ter.name+" data="+AssetDatabase.GetAssetPath(ter.terrainData)+" draw="+ter.drawTreesAndFoliage);foreach(var d in ter.terrainData.detailPrototypes)lines.Add("DETAIL "+(d.prototype?d.prototype.name:d.prototypeTexture?d.prototypeTexture.name:"null"));}File.WriteAllLines(W+"/work/grass-inspect.txt",lines);}
static void GrassRemoveOnly(){var s=Load("10005a");Directory.CreateDirectory(W+"/outputs/GrassRemoval");EditorSceneManager.SaveScene(s,W+"/outputs/GrassRemoval/10005a_before_grass_removal.unity",true);var targets=All(s).Where(t=>FineGrass(t)&&t.gameObject.activeSelf).ToArray();Undo.RecordObjects(targets.Select(t=>(UnityEngine.Object)t.gameObject).ToArray(),"Remove 10005a fine ground grass");foreach(var t in targets)t.gameObject.SetActive(false);EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);File.WriteAllText(W+"/work/grass-removal.txt","Disabled fine ground grass objects="+targets.Length+"\nRemaining active="+All(s).Count(t=>FineGrass(t)&&t.gameObject.activeInHierarchy)+"\nSaved="+!s.isDirty);}
}
#endif
